export const title = "How to Set Up a Closet Office You Can Close After Work";
export const metaTitle = "How to Set Up a Closet Office You Can Close";
export const metaDescription = "Plan two complete arrangements: working and closed. Measure the opening with the doors fully deployed, keep equipment behind the doors' actual closing.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-10";
export const readTime = "13 min";
